/** Who can see this todo? Admin = all (optionally company). Manager = own team only. Member = assigned/created. */
function _todoBelongsToMe(t){
  if(!t) return false;
  if(typeof isAdmin==='function' && isAdmin()){
    // Admin: optionally scope by company view
    try{
      const cid = SESSION.viewCompanyId || 'ALL';
      if(cid && cid !== 'ALL' && t.companyId){
        const n = typeof _normCompanyId==='function' ? _normCompanyId : (x)=>String(x||'');
        if(n(t.companyId) !== n(cid)) return false;
      }
    }catch(e){}
    return true;
  }
  const myEmpObjId = SESSION.empObjId || '';
  const myEmpId = SESSION.empId || '';
  const myName = String(SESSION.name||'').toLowerCase().trim();
  const myKey = typeof _normMobileKey==='function' ? _normMobileKey(SESSION.mobile||SESSION.uid||'') : String(SESSION.mobile||'').replace(/\D/g,'').slice(-10);

  // Assigned to me
  if(t.assignedToEmpId && myEmpObjId && t.assignedToEmpId === myEmpObjId) return true;
  if(!t.assignedToEmpId && t.assignedTo && myName && String(t.assignedTo).toLowerCase().trim() === myName) return true;
  // Created by me
  if(myEmpId && (t.createdBy === myEmpId || t.createdByEmpId === myEmpId)) return true;
  if(myEmpObjId && (t.createdBy === myEmpObjId || t.createdByEmpId === myEmpObjId)) return true;
  if(myName && t.createdByName && String(t.createdByName).toLowerCase().trim() === myName) return true;

  // Manager: team scope
  if(typeof isMgr==='function' && isMgr()){
    const tMgr = typeof _normMobileKey==='function' ? _normMobileKey(t.managerId||'') : String(t.managerId||'').replace(/\D/g,'').slice(-10);
    if(tMgr && myKey && tMgr === myKey) return true;
    // Assigned to someone currently under me
    try{
      const team = (typeof getEmps==='function' ? getEmps() : []) || [];
      const teamIds = new Set(team.map(e=>e && e.id).filter(Boolean));
      const teamPhones = new Set(team.map(e=>typeof _normMobileKey==='function' ? _normMobileKey(e.phone||e.mobile||'') : '').filter(p=>p.length===10));
      if(t.assignedToEmpId && teamIds.has(t.assignedToEmpId)) return true;
      // Legacy todos without managerId: only if creator is still on my roster
      if(!t.managerId && t.createdByEmpId && teamIds.has(t.createdByEmpId)) return true;
    }catch(e){}
    // Do NOT show other managers' tasks (e.g. Vivek's tasks to Keshav)
    return false;
  }
  return false;
}
try{ window._todoBelongsToMe = _todoBelongsToMe; }catch(e){}

